// The MATLAB v4 reader lives in a sibling file. lib.rs is regenerated by
// mmtorust and only declares the top-level packages, so the submodule is
// attached here instead.
#[path = "read_matlab4.rs"]
mod read_matlab4;
use read_matlab4::MatReader;

// Scripting error messages, mirroring the inline `c_add_message(NULL, -1, ...)`
// calls in the C `SimulationResults.c`. Tokens are supplied in the order the
// `%s` placeholders appear in the format string.
static ERROR_UNKNOWN_SUFFIX: ErrorTypes::Message = ErrorTypes::Message {
    id: -1,
    ty: ErrorTypes::MessageType::SCRIPTING,
    severity: ErrorTypes::Severity::ERROR,
    message: Gettext::TranslatableContent::gettext { msgid: literal!("Unknown result-file suffix of file '%s'") },
};
static ERROR_OPEN_FAILED: ErrorTypes::Message = ErrorTypes::Message {
    id: -1,
    ty: ErrorTypes::MessageType::SCRIPTING,
    severity: ErrorTypes::Severity::ERROR,
    message: Gettext::TranslatableContent::gettext { msgid: literal!("Failed to open simulation result %s: %s") },
};
